function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;}
function loadSaved():Saved{try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);return {...parsed,completed:Array.isArray(parsed.completed)?parsed.completed:[],scores:parsed.scores||{},answers:parsed.answers||{},assignmentCompleted:Array.isArray(parsed.assignmentCompleted)?parsed.assignmentCompleted:[],assignmentResponses:parsed.assignmentResponses||{},assignmentScores:parsed.assignmentScores||{},startedAt:parsed.startedAt||localDate()};}}catch{}return{completed:[],scores:{},answers:{},assignmentCompleted:[],assignmentResponses:{},assignmentScores:{},startedAt:localDate()};}
